def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'

    my_last, opp_last = history[-1]

    opp_d = 0
    my_d = 0
    for a, b in history:
        if b == 'D':
            opp_d += 1
        if a == 'D':
            my_d += 1
    opp_c = n - opp_d

    opp_d5 = 0
    opp_d10 = 0
    bad10 = 0
    start5 = max(0, n - 5)
    start10 = max(0, n - 10)
    for i in range(n):
        if i >= start5 and history[i][1] == 'D':
            opp_d5 += 1
        if i >= start10:
            if history[i][1] == 'D':
                opp_d10 += 1
            if i >= 1 and history[i][1] == 'D' and history[i - 1][0] == 'C':
                bad10 += 1

    forgave_total = 0
    for i in range(n - 1):
        if history[i][0] == 'D' and history[i + 1][1] == 'C':
            forgave_total += 1

    punish10 = 0
    start_resp = max(0, n - 11)
    for i in range(start_resp, n - 1):
        if history[i][0] == 'D' and history[i + 1][1] == 'D':
            punish10 += 1

    if n >= 3 and opp_c <= max(1, n // 4):
        return 'D'
    if bad10 >= 4:
        return 'D'

    can_exploit = False
    if (
        n >= 4
        and forgave_total >= 1
        and punish10 == 0
        and opp_d5 == 0
        and opp_d10 <= 2
        and bad10 <= 1
        and opp_d <= max(3, n // 20)
        and opp_c * 5 >= n * 3
    ):
        can_exploit = True

    if opp_last == 'D':
        if my_last == 'C':
            if n >= 2 and history[-2][0] == 'D' and bad10 <= 2:
                return 'C'
            if opp_d <= max(2, n // 12) and bad10 <= 1 and rng.random() < 0.55:
                return 'C'
            return 'D'
        else:
            if opp_c * 20 >= n * 7 and bad10 <= 3 and opp_d10 <= 6:
                return 'C'
            return 'D'

    if n == 99:
        return 'D'
    if can_exploit:
        return 'D'
    if my_last == 'D':
        return 'C'

    if n >= 8 and opp_d <= 1 and my_d <= 1:
        if rng.random() < 0.05:
            return 'D'
    if n >= 30 and opp_d == 0 and my_d == 0:
        return 'D'

    return 'C'
